import React, { useContext } from "react";
import ProductContext from "./store2/product-context";

import './AddProduct.css';
const AddProduct = () => {
  const { openProduct, selectedItem, addItem } = useContext(ProductContext);

  const addToCart = (size) => {
    const item = {
      id: selectedItem.id,
      name: selectedItem.name,
      price: selectedItem.price,
      size: size,
    };
   // addItem(item);
  };

  return (
    <div>
    {openProduct && selectedItem && (
      <div className="addProduct">
        {selectedItem.map((item) => (
          <div key={item.id}>
            <h2>{item.name}</h2>
            <p>Description: {item.description}</p>
            <p>Price: Rs {item.price}</p>
            <button onClick={() => addToCart("Large")}>Buy Large</button>
            <button onClick={() => addToCart("Medium")}>Buy Medium</button>
            <button onClick={() => addToCart("Small")}>Buy Small</button>
          </div>
        ))}
      </div>
    )}
  </div>
  );
};

export default AddProduct;
